import {
  type InitialTableState,
  type RowData,
  type Table,
  type TableFeature,
  type TableOptions,
} from '../hooks/useTable/types.js';
import { type DataTableV2Props } from '../public.api.js';

/**
 * Options for DataTableV2 visual representation
 * @public
 */
export interface DataTableV2VisualVariantProps {
  variant?: {
    /**
     * rowSeparation can be set to 'horizontalDividers' which will provide lines between rows or
     * can be set to 'zebraStripes' which will provide alternate row coloring.
     * @defaultValue 'horizontalDividers'
     */
    rowSeparation?: 'none' | 'horizontalDividers' | 'zebraStripes';

    /**
     * If true provides vertical lines between the columns.
     * @defaultValue false
     */
    verticalDividers?: boolean;

    /**
     * If true provides a border for the table.
     * @defaultValue true
     */
    contained?: boolean;

    /**
     * rowDensity adds spacing around the content inside the row
     * with minimal space for 'condensed', maximum spacing for 'comfortable' and
     * 'default' being medium spacing.
     * @defaultValue 'default'
     */
    rowDensity?: 'default' | 'condensed' | 'comfortable';

    /**
     * fontStyle, sets the font style for the entire data table.
     * This does not overwrite any fontStyle set at the lower level, like columns etc.
     * @defaultValue 'text'
     */
    fontStyle?: 'text' | 'code';
  };
}

// Extension interface to extend the tanstack table state with the visualVariant props
export interface DataTableV2VisualVariantTableState {
  // As all values will be defaulted to not be undefined within the setup,
  // we can resolve typescript here for object and all keys to be required and not undefined.
  visualVariantConfig: Required<
    Required<DataTableV2VisualVariantProps>['variant']
  >;
}

export interface DataTableV2VisualVariantTableInstance {
  getVisualVariantOptions: () => DataTableV2VisualVariantTableState['visualVariantConfig'];
}

export interface DataTableV2VisualVariantCell {
  getVisualVariantOptions: () => DataTableV2VisualVariantTableState['visualVariantConfig'];
}

export const DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT = {
  rowSeparation: 'horizontalDividers',
  verticalDividers: false,
  contained: true,
  rowDensity: 'default',
  fontStyle: 'text',
} as const;

export function useVisualVariant<T>(
  props: DataTableV2Props<T>,
  options: TableOptions<T>,
) {
  options.state = {
    ...options.state,
    visualVariantConfig: {
      rowSeparation:
        props.variant?.rowSeparation ??
        DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.rowSeparation,
      verticalDividers:
        props.variant?.verticalDividers ??
        DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.verticalDividers,
      contained:
        props.variant?.contained ??
        DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.contained,
      rowDensity:
        props.variant?.rowDensity ??
        DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.rowDensity,
      fontStyle:
        props.variant?.fontStyle ??
        DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.fontStyle,
    },
  };
}

export const VisualVariantConfig: TableFeature = {
  getInitialState(state?: InitialTableState) {
    return {
      visualVariantConfig: {
        rowSeparation: DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.rowSeparation,
        verticalDividers:
          DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.verticalDividers,
        contained: DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.contained,
        rowDensity: DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.rowDensity,
        fontStyle: DATA_TABLE_VISUAL_VARIANT_CONFIG_DEFAULT.fontStyle,
      },
      ...state,
    };
  },

  createTable<TData extends RowData>(table: Table<TData>): void {
    table.getVisualVariantOptions = () => {
      return table.getState().visualVariantConfig;
    };
  },
};
